use vstd::prelude::*;

verus! {

/// check_below_threshold returns true exactly when every entry of `l`
/// is strictly less than the threshold `t`.
///
/// We express this in the post‐condition by saying
///   result == (forall i < l.len(): (l@).index(i) < t)
///
/// Here `l@` denotes the specification‐level view of the run‐time vector `l`.
fn check_below_threshold(l: Vec<i8>, t: i8) -> (result: bool)
    ensures
        // The result is true iff for every valid index i,
        // the i-th element of `l` is < t.
        result
          == forall|i: nat| i < l.len() ==>
               (l@).index(i) < t,
{
    let mut idx: usize = 0;
    let mut ok: bool    = true;

    // We iterate idx from 0 to l.len(), maintaining the invariant
    //   ok == (forall j < idx: (l@).index(j) < t).
    // At the end, idx == l.len(), so ok exactly matches the
    // forall‐property in the postcondition.
    while idx < l.len()
        invariant
            // idx is always a valid prefix bound
            idx <= l.len(),
            // ok reflects that every element 0..idx-1 is < t
            ok
              == forall|j: nat| j < idx ==>
                   (l@).index(j) < t,
        decreases l.len() - idx
    {
        let v: i8 = l[idx];
        if !(v < t) {
            ok = false;
        }
        idx += 1;
    }

    // Return the flag `ok`. By the invariant, at idx == l.len() we have
    //  ok == forall j < l.len(): (l@)[j] < t
    ok
}

} // end verus!

fn main() {
    // Simple smoke tests:
    assert!(check_below_threshold(vec![] as Vec<i8>,  0));
    assert!(check_below_threshold(vec![ -5, -1, -1 ],  0));
    assert!(!check_below_threshold(vec![ -5, 10,  -1 ], 0));
    assert!(!check_below_threshold(vec![  0,  0,   0 ], 0));
}